const item = $input.first();
const body = item.json.body ?? {};
const worksheet = item.binary?.worksheet;
const pdf = item.binary?.invoice_pdf;

if (!worksheet) {
  throw new Error('Missing multipart file field: worksheet');
}
if (!pdf) {
  throw new Error('Missing multipart file field: invoice_pdf');
}

const worksheetName = worksheet.fileName ?? '';
const pdfName = pdf.fileName ?? '';
if (!pdfName.toLowerCase().endsWith('.pdf')) {
  throw new Error(`The invoice file must be a PDF: ${pdfName || '(unnamed)'}`);
}

const match = worksheetName.match(/(?:^|[_-])(\d{4})(0[1-9]|1[0-2])(?:\d{2})?(?=\.[^.]+$|[_-]|$)/);
if (!match) {
  throw new Error(`The WorkSheet filename must contain YYYYMM or YYYYMMDD after _ or -: ${worksheetName}`);
}

if (!body.client_email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.client_email)) {
  throw new Error('A valid client_email form field is required');
}
for (const [field, link] of Object.entries({ worksheet_link: body.worksheet_link, invoice_pdf_link: body.invoice_pdf_link })) {
  if (!link || !/^https?:\/\//.test(link)) {
    throw new Error(`A valid ${field} form field is required`);
  }
}

return [{
  json: {
    ...item.json,
    billing_month: Number(match[2]),
    worksheet_name: worksheetName,
    invoice_pdf_name: pdfName,
  },
  binary: item.binary,
}];
